import itertools
def ok(n):
    total = n * (n + 1) // 2
    if total % 3: return False
    return any(sum(k + 1 for k in range(n) if c[k] == g) == total // 3 for c in itertools.product(range(3), repeat=n) for g in (0,) if all(sum(k + 1 for k in range(n) if c[k] == h) == total // 3 for h in (1, 2)))
result = [n for n in range(1, 13) if ok(n)]

import functools
@functools.lru_cache(None)
def t(cells):
    if not cells: return 1
    x, y = min(cells)
    return sum(t(cells - {(x, y), n}) for n in ((x + 1, y), (x, y + 1)) if n in cells)
result = t(frozenset((x, y) for x in range(8) for y in range(3)))
